def is_predictable(A, T):
    OPT = optimal_schedule(T)
    if not feasible(OPT, T):
        return True  # Vacuously
    sched_A = simulate(A, T)
    return feasible(sched_A, T)

def lemma_3_1(T_subset, m, T_k):
    if len(T_subset) > m:
        return False
    hyper = lcm([task.T for task in T_subset])
    return hyper <= ((2*m - 1)/m) * T_k

def rm_us_light(T, m):
    bound = m / (3*m - 2)
    for task in T:
        assign_capacity(task, bound)
    return rm_schedule(T)

def theorem_3(T, m):
    if U(T) > m/3:
        return False
    return rm_us(m/(3*m-2), T).feasible
